#!/usr/bin/env node

/**
 * Postinstall for agent-ctrl.
 *
 * The npm tarball does NOT bundle native binaries. On install we detect the
 * platform/arch, download the matching prebuilt binary from this version's
 * GitHub Release, drop it into bin/, chmod it on POSIX, and (for Windows
 * global installs) rewrite npm's .cmd/.ps1 shims so the .exe runs directly
 * with zero Node overhead.
 *
 * Supported targets in v0.1.x: Windows x64, macOS arm64, macOS x64.
 *
 * The script must never throw - postinstall failures break installs.
 */

import {
  chmodSync,
  createWriteStream,
  existsSync,
  mkdirSync,
  unlinkSync,
  writeFileSync,
} from "fs"
import { dirname, join } from "path"
import { fileURLToPath } from "url"
import { platform, arch } from "os"
import { execSync } from "child_process"
import { get } from "https"

const __dirname = dirname(fileURLToPath(import.meta.url))
const projectRoot = join(__dirname, "..")
const binDir = join(projectRoot, "bin")

const GITHUB_REPO = "k4cper-g/agent-ctrl"

const packageJson = JSON.parse(
  await import("fs").then((m) =>
    m.readFileSync(join(projectRoot, "package.json"), "utf8"),
  ),
)
const version = packageJson.version

function getBinaryName() {
  const os = platform()
  const cpuArch = arch()

  if (os === "win32" && cpuArch === "x64") return "agent-ctrl-win32-x64.exe"
  if (os === "darwin" && cpuArch === "arm64") return "agent-ctrl-darwin-arm64"
  if (os === "darwin" && cpuArch === "x64") return "agent-ctrl-darwin-x64"

  return null
}

function noticeUnsupported() {
  console.log("")
  console.log("agent-ctrl: this platform is not supported in v0.1.x.")
  console.log(
    `  Detected: ${platform()}-${arch()}.`,
  )
  console.log(
    "  v0.1.x supports Windows x64, macOS arm64, and macOS x64.",
  )
  console.log("  Linux/iOS/Android are on the roadmap.")
  console.log("")
}

function downloadFile(url, dest) {
  return new Promise((resolve, reject) => {
    const file = createWriteStream(dest)
    const request = (currentUrl) => {
      get(currentUrl, (res) => {
        if (res.statusCode === 301 || res.statusCode === 302 || res.statusCode === 307) {
          request(res.headers.location)
          return
        }
        if (res.statusCode !== 200) {
          reject(new Error(`HTTP ${res.statusCode} for ${currentUrl}`))
          return
        }
        res.pipe(file)
        file.on("finish", () => file.close(() => resolve()))
      }).on("error", (err) => {
        try {
          unlinkSync(dest)
        } catch {}
        reject(err)
      })
    }
    request(url)
  })
}

async function main() {
  const binaryName = getBinaryName()

  if (!binaryName) {
    noticeUnsupported()
    return
  }

  if (!existsSync(binDir)) {
    mkdirSync(binDir, { recursive: true })
  }

  const binaryPath = join(binDir, binaryName)

  if (existsSync(binaryPath)) {
    if (platform() !== "win32") {
      try {
        chmodSync(binaryPath, 0o755)
      } catch {}
    }
    console.log(`agent-ctrl: native binary already present (${binaryName}).`)
    if (platform() === "win32") await fixWindowsShims(binaryName)
    return
  }

  const url = `https://github.com/${GITHUB_REPO}/releases/download/v${version}/${binaryName}`
  console.log(`agent-ctrl: downloading ${binaryName} for v${version} ...`)
  console.log(`  ${url}`)

  try {
    await downloadFile(url, binaryPath)
    if (platform() !== "win32") {
      chmodSync(binaryPath, 0o755)
    }
    console.log(`agent-ctrl: ready (${binaryName}).`)
  } catch (err) {
    console.warn(
      `agent-ctrl: could not download native binary (${err.message}).`,
    )
    console.warn(
      `  Install will still complete; running 'agent-ctrl' will fail until you`,
    )
    console.warn(
      `  reinstall or run 'npm run build:native' from a source checkout.`,
    )
    return
  }

  if (platform() === "win32") {
    await fixWindowsShims(binaryName)
  }
}

/**
 * On global installs (npm i -g), npm generates .cmd/.ps1 shims that go through
 * /bin/sh - broken on Windows. Overwrite them to invoke the .exe directly.
 */
async function fixWindowsShims(binaryName) {
  let npmBinDir
  try {
    npmBinDir = execSync("npm prefix -g", { encoding: "utf8" }).trim()
  } catch {
    return
  }

  const cmdShim = join(npmBinDir, "agent-ctrl.cmd")
  const ps1Shim = join(npmBinDir, "agent-ctrl.ps1")

  if (!existsSync(cmdShim)) {
    return
  }

  const relBinary = `node_modules\\@agent-ctrl\\cli\\bin\\${binaryName}`
  const absBinary = join(npmBinDir, relBinary)
  if (!existsSync(absBinary)) {
    return
  }

  try {
    const cmdContent = `@ECHO off\r\n"%~dp0${relBinary}" %*\r\n`
    writeFileSync(cmdShim, cmdContent)

    const ps1Content =
      `#!/usr/bin/env pwsh\r\n` +
      `$basedir = Split-Path $MyInvocation.MyCommand.Definition -Parent\r\n` +
      `& "$basedir\\${relBinary}" $args\r\n` +
      `exit $LASTEXITCODE\r\n`
    writeFileSync(ps1Shim, ps1Content)

    console.log("agent-ctrl: shims patched for direct binary invocation.")
  } catch (err) {
    console.log(
      `agent-ctrl: could not optimize shims (${err.message}); JS wrapper still works.`,
    )
  }
}

main().catch((err) => {
  console.warn(`agent-ctrl postinstall warning: ${err.message}`)
})

"use client"

import * as React from "react"
import { Check, Copy } from "lucide-react"

const COMMANDS = [
  {
    id: "humans",
    label: "For humans",
    command: "npm install -g @agent-ctrl/cli",
  },
  {
    id: "agents",
    label: "For agents",
    command: "npx skills add k4cper-g/agent-ctrl",
  },
] as const

type Id = (typeof COMMANDS)[number]["id"]

export function InstallTabs() {
  const [active, setActive] = React.useState<Id>("humans")
  const [copied, setCopied] = React.useState(false)
  const command = COMMANDS.find((c) => c.id === active)!.command

  async function onCopy() {
    try {
      await navigator.clipboard.writeText(command)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1500)
    } catch {
      // clipboard unavailable; ignore
    }
  }

  return (
    <div className="flex flex-col items-center gap-6">
      <div className="flex items-center gap-4 font-mono text-sm">
        {COMMANDS.map((c, i) => (
          <React.Fragment key={c.id}>
            {i > 0 && (
              <span aria-hidden className="text-muted-foreground/40">
                |
              </span>
            )}
            <button
              type="button"
              onClick={() => {
                setActive(c.id)
                setCopied(false)
              }}
              className={
                c.id === active
                  ? "text-foreground"
                  : "text-muted-foreground hover:text-foreground"
              }
            >
              {c.label}
            </button>
          </React.Fragment>
        ))}
      </div>
      <div className="inline-flex items-center gap-3 border border-border bg-card px-5 py-2.5 font-mono text-sm text-foreground">
        <span className="text-muted-foreground">$</span>
        <span className="select-all">{command}</span>
        <button
          type="button"
          onClick={onCopy}
          aria-label={copied ? "Copied" : "Copy command"}
          className="ml-1 text-muted-foreground hover:text-foreground"
        >
          {copied ? (
            <Check className="size-3.5" />
          ) : (
            <Copy className="size-3.5" />
          )}
        </button>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { Check, Copy } from "lucide-react"

export function InstallCommand({ command }: { command: string }) {
  const [copied, setCopied] = React.useState(false)

  async function onCopy() {
    try {
      await navigator.clipboard.writeText(command)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1500)
    } catch {
      // clipboard unavailable; ignore
    }
  }

  return (
    <div className="inline-flex h-7 items-center gap-2 border border-border px-3 font-mono text-xs text-foreground">
      <span className="text-muted-foreground">$</span>
      <span className="select-all">{command}</span>
      <button
        type="button"
        onClick={onCopy}
        aria-label={copied ? "Copied" : "Copy install command"}
        className="ml-1 text-muted-foreground hover:text-foreground"
      >
        {copied ? (
          <Check className="size-3" />
        ) : (
          <Copy className="size-3" />
        )}
      </button>
    </div>
  )
}

//! The cross-platform action vocabulary.
//!
//! Mirrors the platform-agnostic subset of agent-browser's action dispatcher.
//! Browser-specific verbs (`tab_*`, `waitforurl`, `route`, `har_*`, cookie
//! storage) are intentionally absent - they have no native analog. New
//! cross-platform verbs that the browser doesn't need (`switch_app`,
//! `focus_window`) are added at the bottom.

use serde::{Deserialize, Serialize};

use crate::node::RefId;

/// Action a [`Surface`](crate::surface::Surface) can be asked to perform.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Action {
    /// Single primary-button click on the referenced element.
    Click {
        /// Target element.
        ref_id: RefId,
    },
    /// Double primary-button click.
    DoubleClick {
        /// Target element.
        ref_id: RefId,
    },
    /// Secondary-button (right) click.
    RightClick {
        /// Target element.
        ref_id: RefId,
    },
    /// Move the cursor over the element.
    Hover {
        /// Target element.
        ref_id: RefId,
    },
    /// Move keyboard focus to the element.
    Focus {
        /// Target element.
        ref_id: RefId,
    },
    /// Type a string at the current focus.
    Type {
        /// Text to type.
        text: String,
    },
    /// Replace the value of an editable element.
    Fill {
        /// Target element.
        ref_id: RefId,
        /// New value.
        value: String,
    },
    /// Press one or more keys (e.g. `"Enter"`, `"Ctrl+A"`).
    Press {
        /// Keys in platform-agnostic notation.
        keys: String,
    },
    /// Press a key down without releasing.
    KeyDown {
        /// Key name.
        key: String,
    },
    /// Release a previously-pressed key.
    KeyUp {
        /// Key name.
        key: String,
    },
    /// Scroll the referenced element by `(dx, dy)` logical pixels.
    /// When `ref_id` is `None`, scrolls the focused viewport.
    Scroll {
        /// Element to scroll within.
        #[serde(skip_serializing_if = "Option::is_none")]
        ref_id: Option<RefId>,
        /// Horizontal delta.
        dx: f64,
        /// Vertical delta.
        dy: f64,
    },
    /// Drag from one element to another.
    Drag {
        /// Source element.
        from: RefId,
        /// Destination element.
        to: RefId,
    },
    /// Choose an option in a select / combo box / list box.
    Select {
        /// Select container.
        ref_id: RefId,
        /// Value or visible text of the option to choose.
        value: String,
    },
    /// Select all content in the focused field, or in the referenced field.
    SelectAll {
        /// Field to operate on; `None` uses current focus.
        #[serde(skip_serializing_if = "Option::is_none")]
        ref_id: Option<RefId>,
    },
    /// Set a checkable control to the checked state.
    Check {
        /// Target element.
        ref_id: RefId,
    },
    /// Set a checkable control to the unchecked state.
    Uncheck {
        /// Target element.
        ref_id: RefId,
    },
    /// Toggle a checkable control.
    Toggle {
        /// Target element.
        ref_id: RefId,
    },
    /// Clear an editable field.
    Clear {
        /// Target element.
        ref_id: RefId,
    },
    /// Read from, write to, copy from, or paste from the host clipboard.
    Clipboard {
        /// Clipboard operation to perform.
        op: ClipboardOp,
    },
    /// Raw mouse event in screen coordinates.
    Mouse {
        /// Mouse operation to perform.
        op: MouseOp,
    },
    /// Visually mark an element for human debugging.
    Highlight {
        /// Target element.
        ref_id: RefId,
        /// Highlight duration in milliseconds.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        duration_ms: Option<u64>,
    },
    /// Scroll the element into view without focusing it.
    ScrollIntoView {
        /// Target element.
        ref_id: RefId,
    },
    /// Sleep for `ms` milliseconds.
    Wait {
        /// Duration in milliseconds.
        ms: u64,
    },
    /// Bring a different application to the foreground.
    SwitchApp {
        /// Platform application id (bundle id, package name, AUMID).
        app_id: String,
    },
    /// Bring a different window of the current app to the foreground.
    FocusWindow {
        /// Platform window id.
        window_id: String,
    },
    /// Capture a screenshot, optionally cropped to a region.
    Screenshot {
        /// Optional crop region in screen coordinates.
        #[serde(skip_serializing_if = "Option::is_none")]
        region: Option<Region>,
        /// Optional target. When absent, `region` preserves the legacy shape.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        target: Option<ScreenshotTarget>,
        /// Draw visible ref labels on the screenshot when supported.
        #[serde(default, skip_serializing_if = "is_false")]
        annotated: bool,
    },
}

/// Clipboard operation.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum ClipboardOp {
    /// Read Unicode text from the clipboard.
    Read,
    /// Replace clipboard text.
    Write {
        /// Text to store.
        text: String,
    },
    /// Send the platform copy shortcut.
    Copy,
    /// Send the platform paste shortcut.
    Paste,
}

/// Raw mouse operation.
#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum MouseOp {
    /// Move the cursor to screen coordinates.
    Move {
        /// X coordinate.
        x: i32,
        /// Y coordinate.
        y: i32,
    },
    /// Press a mouse button at screen coordinates.
    Down {
        /// X coordinate.
        x: i32,
        /// Y coordinate.
        y: i32,
        /// Button to press.
        button: MouseButton,
    },
    /// Release a mouse button at screen coordinates.
    Up {
        /// X coordinate.
        x: i32,
        /// Y coordinate.
        y: i32,
        /// Button to release.
        button: MouseButton,
    },
    /// Send a wheel event at screen coordinates.
    Wheel {
        /// X coordinate.
        x: i32,
        /// Y coordinate.
        y: i32,
        /// Horizontal wheel delta.
        dx: i32,
        /// Vertical wheel delta.
        dy: i32,
    },
}

/// Mouse button name.
#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MouseButton {
    /// Primary button.
    Left,
    /// Secondary button.
    Right,
    /// Middle button.
    Middle,
}

/// Screenshot target.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum ScreenshotTarget {
    /// Capture the current pinned window.
    Window,
    /// Capture the desktop or virtual screen.
    Desktop,
    /// Capture a specific region.
    Region {
        /// Region to capture.
        region: Region,
    },
    /// Capture the bounds of an element ref.
    Ref {
        /// Element whose bounds define the screenshot region.
        ref_id: RefId,
    },
}

/// Pixel rectangle in screen-space.
#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
pub struct Region {
    /// Left edge.
    pub x: i32,
    /// Top edge.
    pub y: i32,
    /// Width in pixels.
    pub w: u32,
    /// Height in pixels.
    pub h: u32,
}

#[allow(clippy::trivially_copy_pass_by_ref)]
fn is_false(b: &bool) -> bool {
    !*b
}

/// Result of executing an [`Action`].
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ActionResult {
    /// Whether the action completed successfully.
    pub ok: bool,
    /// Optional human-readable status.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
    /// Free-form payload (screenshot bytes, returned text, etc.).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub data: Option<serde_json::Value>,
}

impl ActionResult {
    /// Build a successful result with no payload.
    #[must_use]
    pub fn ok() -> Self {
        Self {
            ok: true,
            message: None,
            data: None,
        }
    }

    /// Build a failure result with a message.
    #[must_use]
    pub fn fail(message: impl Into<String>) -> Self {
        Self {
            ok: false,
            message: Some(message.into()),
            data: None,
        }
    }
}

#!/usr/bin/env node

/**
 * Cross-platform CLI wrapper for agent-ctrl.
 *
 * The wrapper detects platform/arch and spawns the matching native binary
 * shipped by postinstall (`agent-ctrl-<os>-<arch>[.exe]` in this directory).
 * It enables `npx @agent-ctrl/cli` on Windows where shell scripts don't work
 * and lets the native binary run directly when postinstall has patched the
 * global shims.
 *
 * Supported in v0.1.x: Windows x64, macOS arm64, macOS x64.
 * Linux is on the roadmap but not in this release.
 */

import { spawn } from "child_process"
import { existsSync } from "fs"
import { dirname, join } from "path"
import { fileURLToPath } from "url"
import { platform, arch } from "os"

const __dirname = dirname(fileURLToPath(import.meta.url))

function getBinaryName() {
  const os = platform()
  const cpuArch = arch()

  if (os === "win32" && cpuArch === "x64") return "agent-ctrl-win32-x64.exe"
  if (os === "darwin" && cpuArch === "arm64") return "agent-ctrl-darwin-arm64"
  if (os === "darwin" && cpuArch === "x64") return "agent-ctrl-darwin-x64"

  return null
}

function main() {
  const binaryName = getBinaryName()

  if (!binaryName) {
    console.error(
      `agent-ctrl: ${platform()}-${arch()} is not yet supported.`,
    )
    console.error(
      "v0.1.x supports Windows x64, macOS arm64, and macOS x64. Linux is",
    )
    console.error(
      "on the roadmap; see https://github.com/k4cper-g/agent-ctrl",
    )
    process.exit(1)
  }

  const binaryPath = join(__dirname, binaryName)

  if (!existsSync(binaryPath)) {
    console.error(`agent-ctrl: native binary missing at ${binaryPath}.`)
    console.error("")
    console.error("Reinstall the package, or build from source:")
    console.error("  git clone https://github.com/k4cper-g/agent-ctrl")
    console.error("  cd agent-ctrl && npm run build:native")
    process.exit(1)
  }

  const child = spawn(binaryPath, process.argv.slice(2), {
    stdio: "inherit",
    windowsHide: false,
  })

  child.on("error", (err) => {
    console.error(`agent-ctrl: failed to launch binary: ${err.message}`)
    process.exit(1)
  })

  child.on("close", (code) => {
    process.exit(code ?? 0)
  })
}

main()

